import { useState } from "react";
import { NavLink, Outlet, Link } from "react-router-dom";

// تأكد من أن الـ href تتطابق مع المسارات (Routes) المعرفة في App.js
const NAV_ITEMS = [
  { id: "dashboard",    label: "Dashboard",       icon: "📊", href: "/student/dashboard" },
  { id: "search",       label: "Find offers",     icon: "🔍", href: "/student/search" },
  { id: "applications", label: "My applications", icon: "📋", href: "/student/applications" },
  { id: "profile",      label: "My profile",      icon: "👤", href: "/student/profile" },
];

function Sidebar({ closeMobileMenu }) {
  return (
    <aside className="flex flex-col h-full bg-white border-r border-slate-200" style={{ width: 240 }}>
      {/* Logo */}
      <div className="px-5 py-5 border-b border-slate-100">
        <Link to="/" className="font-syne font-extrabold text-xl text-slate-900 tracking-tight">
          Stag<span className="text-[#2E7DF7]">.</span>io
        </Link>
        <div className="mt-0.5 text-xs text-slate-400 font-medium">Student Portal</div>
      </div>

      {/* Nav */}
      <nav className="flex-1 p-3 space-y-1 overflow-y-auto">
        <div className="text-xs font-semibold text-slate-400 uppercase tracking-widest px-2 py-2">Menu</div>
        {NAV_ITEMS.map((item) => (
          <NavLink
            key={item.id}
            to={item.href}
            onClick={closeMobileMenu} // لإغلاق القائمة في الجوال عند الضغط
            className={`({ isActive }) => 
              sidebar-link flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-medium transition-all ${
                isActive 
                ? "bg-[#2E7DF7]/10 text-[#2E7DF7] font-semibold" 
                : "text-slate-500 hover:text-slate-800 hover:bg-slate-50"
              }
            `}
          >
            <span className="icon text-lg">{item.icon}</span>
            <span>{item.label}</span>
            {item.id === "applications" && (
              <span className="ml-auto bg-[#2E7DF7] text-white text-[10px] px-1.5 py-0.5 rounded-md font-bold">3</span>
            )}
          </NavLink>
        ))}
      </nav>

      {/* User card */}
      <div className="p-3 border-t border-slate-100">
        <div className="flex items-center gap-3 p-3 rounded-xl hover:bg-slate-50 cursor-pointer transition-colors">
          <div className="w-9 h-9 rounded-full bg-gradient-to-br from-[#5aaee8] to-[#2E7DF7] flex items-center justify-center text-sm font-bold text-white shrink-0">
            AB
          </div>
          <div className="flex-1 min-w-0">
            <div className="text-sm font-semibold text-slate-800 truncate">Amira Benali</div>
            <div className="text-xs text-slate-400 truncate">L3 Informatique</div>
          </div>
        </div>
        <Link to="/login" className="block w-full mt-1 text-xs text-slate-400 hover:text-red-500 py-2 transition-colors text-left px-3">
          Sign out →
        </Link>
      </div>
    </aside>
  );
}

export default function StudentLayout() {
  const [mobileOpen, setMobileOpen] = useState(false);

  return (
    <div className="flex h-screen overflow-hidden bg-slate-50/50">
      
      {/* Sidebar for Desktop */}
      <div className="hidden md:flex shrink-0 h-full">
        <Sidebar />
      </div>

      {/* Mobile Sidebar Overlay */}
      {mobileOpen && (
        <div 
          className="fixed inset-0 z-40 bg-slate-900/20 backdrop-blur-sm md:hidden" 
          onClick={() => setMobileOpen(false)} 
        />
      )}

      {/* Mobile Sidebar Content */}
      <div className={`è`}>
        <Sidebar closeMobileMenu={() => setMobileOpen(false)} />
      </div>
      {/* Main Content Area */}
      <div className="flex-1 flex flex-col overflow-hidden">
        
        {/* Topbar for Mobile */}
        <div className="md:hidden flex items-center justify-between px-4 py-3 bg-white border-b border-slate-200">
          <button onClick={() => setMobileOpen(true)} className="p-2">
            <div className="w-5 h-0.5 bg-slate-700 mb-1"></div>
            <div className="w-5 h-0.5 bg-slate-700 mb-1"></div>
            <div className="w-5 h-0.5 bg-slate-700"></div>
          </button>
          <span className="font-syne font-extrabold text-slate-900">Stag<span className="text-[#2E7DF7]">.</span>io</span>
          <div className="w-8 h-8 rounded-full bg-[#2E7DF7] flex items-center justify-center text-[10px] font-bold text-white">AB</div>
        </div>

        <main className="flex-1 overflow-y-auto p-4 md:p-8">
          {/* Outlet هو المكان الذي سيظهر فيه محتوى الصفحة (Dashboard, Search, etc.) */}
          <Outlet />
        </main>
      </div>
    </div>
  );
}
